import re

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = {}
    current_section = None
    last_key = None

    for line in text.splitlines():
        stripped = line.strip()

        # Rule 3: Ignore empty or comment lines
        if not stripped or stripped[0] in (';', '#'):
            last_key = None
            continue

        # Rule 6: Continuation lines
        if line[0] in (' ', '\t'):
            if last_key is not None and current_section is not None:
                sections[current_section][last_key] += '\n' + stripped
                continue
            raise ValueError("Malformed continuation line without preceding key")

        # Rule 1: Section headers
        section_match = re.match(r'^\s*\[\s*([^\]]+)\s*\]\s*$', line)
        if section_match:
            current_section = section_match.group(1)
            if current_section not in sections:
                sections[current_section] = {}
            last_key = None
            continue

        # Rule 10: Key before any section
        if current_section is None:
            raise ValueError("Key line before any section header")

        # Rule 2: Key-value splitting
        eq_pos = line.find('=')
        colon_pos = line.find(':')
        if eq_pos == -1 and colon_pos == -1:
            raise ValueError(f"Malformed line: {line!r}")

        split_pos = eq_pos if eq_pos != -1 and (colon_pos == -1 or eq_pos < colon_pos) else colon_pos
        key = line[:split_pos].strip().lower()
        if not key:
            raise ValueError(f"Empty key in line: {line!r}")

        raw_val = line[split_pos + 1:]

        # Rule 4 & 5: Quotes and inline comments
        lstrip_val = raw_val.lstrip()
        if lstrip_val.startswith('"'):
            close_idx = lstrip_val.find('"', 1)
            if close_idx == -1:
                raise ValueError(f"Unclosed quote in: {line!r}")
            value = lstrip_val[1:close_idx]
        else:
            cm = re.search(r'[ \t]+[;#]', raw_val)
            c_pos = cm.start() if cm else -1
            value = raw_val[:c_pos] if c_pos != -1 else raw_val
            value = value.strip()

        sections[current_section][key] = value
        last_key = key

    # Rule 8: DEFAULT section inheritance
    if 'DEFAULT' in sections:
        defaults = sections['DEFAULT']
        for sec in sections:
            if sec == 'DEFAULT':
                continue
            for k, v in defaults.items():
                if k not in sections[sec]:
                    sections[sec][k] = v

    # Rule 9: Interpolation resolution
    _RE_INTERP = re.compile(r'\$\{([^}]+)\}')

    def resolve(val: str, sec: str, visiting: set[tuple[str, str]]) -> str:
        def replacer(m: re.Match) -> str:
            ref = m.group(1)
            if ':' in ref:
                ref_sec, ref_key = ref.split(':', 1)
                ref_key = ref_key.strip().lower()
                ref_sec = ref_sec.strip()
            else:
                ref_sec = sec
                ref_key = ref.strip().lower()

            if ref_sec not in sections or ref_key not in sections[ref_sec]:
                raise KeyError(f"Missing reference: {ref_sec}:{ref_key}")
            if (ref_sec, ref_key) in visiting:
                raise ValueError("Interpolation cycle detected")

            visiting.add((ref_sec, ref_key))
            try:
                return resolve(sections[ref_sec][ref_key], ref_sec, visiting)
            finally:
                visiting.remove((ref_sec, ref_key))

        return _RE_INTERP.sub(replacer, val)

    resolved_sections: dict[str, dict[str, str]] = {}
    for sec in sections:
        resolved_sections[sec] = {}
        for k in sections[sec]:
            resolved_sections[sec][k] = resolve(sections[sec][k], sec, set())

    # Rule 8: DEFAULT is not returned
    resolved_sections.pop('DEFAULT', None)
    return resolved_sections
