from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def _remove_expired(self):
        now = self.clock()
        expired_keys = [k for k, (_, exp) in self.cache.items() if now >= exp]
        for k in expired_keys:
            self.cache.pop(k)
            self.expirations += 1

    def put(self, key, value):
        if self.capacity == 0:
            return

        now = self.clock()
        if key in self.cache:
            self.cache[key] = (value, now + self.ttl)
            self.cache.move_to_end(key)
        else:
            if len(self.cache) >= self.capacity:
                self._remove_expired()
                if len(self.cache) >= self.capacity:
                    self.cache.popitem(last=False)
                    self.evictions += 1

            self.cache[key] = (value, now + self.ttl)
            self.cache.move_to_end(key)

    def get(self, key, default=None):
        if self.capacity == 0:
            self.misses += 1
            return default

        now = self.clock()
        if key in self.cache:
            value, expiry = self.cache[key]
            if now >= expiry:
                del self.cache[key]
                self.expirations += 1
                self.misses += 1
                return default

            self.cache.move_to_end(key)
            self.hits += 1
            return value
        else:
            self.misses += 1
            return default

    def __len__(self):
        if self.capacity == 0:
            return 0
        now = self.clock()
        return sum(1 for _, (_, exp) in self.cache.items() if now < exp)

    def stats(self):
        return {
            "hits": self.hits,
            "misses": self.misses,
            "evictions": self.evictions,
            "expirations": self.expirations
        }
