import re

def parse_duration(s: str) -> int:
    pattern = r'\s*(?:([0-9]+)\s*h)?\s*(?:([0-9]+)\s*m)?\s*(?:([0-9]+)\s*s)?\s*'
    match = re.fullmatch(pattern, s, re.IGNORECASE)
    if not match:
        raise ValueError("Invalid duration string")
    h, m, sec = match.groups()
    if h is None and m is None and sec is None:
        raise ValueError("Empty or blank string")
    total = 0
    if h is not None:
        total += int(h) * 3600
    if m is not None:
        total += int(m) * 60
    if sec is not None:
        total += int(sec)
    return total
